int[] a = {1, 3, 5, 7, 9, 11, 13, 15};   // sorted, n = 8
int target = 13, low = 0, high = a.length - 1, steps = 0;
while (low <= high) {
    int mid = (low + high) / 2;
    steps++;
    if (a[mid] == target) break;
    if (a[mid] < target) low = mid + 1; else high = mid - 1;
}
System.out.println(steps);

