static int find(int[] data, int target) {
    Arrays.sort(data);                  // sorted again on every call
    int low = 0, high = data.length - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (data[mid] == target) return mid;
        if (data[mid] < target) low = mid + 1; else high = mid - 1;
    }
    return -1;
}

