int[] a = {50, 40, 30, 20, 10};   // sorted DESCENDING
int target = 50, low = 0, high = a.length - 1, found = -1;
while (low <= high) {             // standard ascending binary search
    int mid = (low + high) / 2;
    if (a[mid] == target) { found = mid; break; }
    if (a[mid] < target) low = mid + 1; else high = mid - 1;
}
System.out.println(found);

